-- ================================================================================================
-- Cabo Cope y Puntas de Calnegre · N2 completo: espacio, hábitats, especies y vínculos.
--
-- GENERADO por Tools/catalogo-nacional/build-park-sql.js desde Frontend\Data\parks\murcia\cabo-cope-puntas-calnegre\park.json
-- y Data/parks/murcia/cabo-cope-puntas-calnegre/geo/habitats.geojson. No editar a mano: regenerar con
--   node Tools/catalogo-nacional/build-park-sql.js --park cabo-cope-puntas-calnegre
--
-- Hace falta porque Frontend/Js/data.js da PRIORIDAD a la API sobre el park.json empaquetado:
-- con backend desplegado, un espacio que no esté en la base de datos no existe para el usuario.
--
-- Contenido: 1 espacio · 15 hábitats · 97 especies · 308 vínculos especie↔hábitat.
-- Los puntos de interés van aparte, en `n3-pois-<slug>.sql` (build-poi-sql.js).
--
-- ORDEN: la fila de `parks` va PRIMERO y no es opcional. Sin ella los INSERT ... SELECT de
-- abajo no encuentran nada y cargan CERO filas sin dar ningún error.
--
-- Idempotente: ON DUPLICATE KEY UPDATE sobre las claves únicas del esquema. Aplicar con:
--   docker exec -i naturdex-db-1 sh -c 'MYSQL_PWD="$MYSQL_ROOT_PASSWORD" mysql --default-character-set=utf8mb4 naturadex' < Database\cabo-cope-puntas-calnegre-n2.sql
-- ================================================================================================

SET NAMES utf8mb4;

-- ------------------------------------------------------------------------------------------------
-- 1. El espacio. Sin esta fila, TODO lo demás carga cero filas en silencio.
-- ------------------------------------------------------------------------------------------------
INSERT INTO parks (slug, name, category, region, province, municipality, description, latitude, longitude, status)
VALUES ('cabo-cope-puntas-calnegre', 'Cabo Cope y Puntas de Calnegre', 'Parque Regional', 'Región de Murcia', 'Murcia', 'Águilas y Lorca', 'Diecisiete kilómetros de litoral casi virgen entre Águilas y Mazarrón: calas encajadas, acantilados a plomo sobre el mar y matorral semiárido.', 37.47595, -1.47759, 'available')
ON DUPLICATE KEY UPDATE
    name = VALUES(name), category = VALUES(category), region = VALUES(region),
    province = VALUES(province), municipality = VALUES(municipality),
    description = VALUES(description), latitude = VALUES(latitude),
    longitude = VALUES(longitude), status = VALUES(status);

-- ------------------------------------------------------------------------------------------------
-- 2. Hábitats (15). `geometry` sale del geojson; sin ella el mapa dibuja un círculo.
-- ------------------------------------------------------------------------------------------------
INSERT INTO habitats (park_id, slug, code, name, habitat_type, description, is_priority, latitude, longitude, color, geometry, review_note, hic_subtipos, fitosociologia, origen, fuentes, solo_curada, audio_url, audio_transcript, image_url, image_attribution, image_note)
