    SELECT 'dunas-malcomietalia', '2230', 'Dunas con céspedes del Malcomietalia', 'Litoral', 'Claros de arena entre el matorral dunar en los que, tras las lluvias, germina un césped efímero de plantas diminutas que florecen y se secan en pocas semanas. Pasan el resto del año como semilla enterrada, de modo que durante casi todo el verano el sitio parece arena vacía. Es un hábitat que solo se ve entero unas semanas al año, y por eso se destruye sin que nadie note que había algo.', 0, 37.507063, -1.416075, '#d9b97e', '{"type":"MultiPolygon","coordinates":[[[[-1.456769,37.488654],[-1.456772,37.488657],[-1.456774,37.488706],[-1.456746,37.488854],[-1.456688,37.488958],[-1.4566,37.489074],[-1.456572,37.489092],[-1.456532,37.489118],[-1.456532,37.489118],[-1.456572,37.489092],[-1.456599,37.489075],[-1.456687,37.488958],[-1.456746,37.488854],[-1.456773,37.488706],[-1.456771,37.488658],[-1.456768,37.488654],[-1.456769,37.488654]]],[[[-1.45637,37.489118],[-1.45637,37.489118],[-1.456332,37.489135],[-1.456332,37.489135],[-1.45637,37.489118]]],[[[-1.456118,37.489122],[-1.456119,37.489122],[-1.456103,37.489143],[-1.456104,37.489165],[-1.456103,37.489165],[-1.456102,37.489143],[-1.456118,37.489122]]],[[[-1.456053,37.489167],[-1.456053,37.489167],[-1.456017,37.489182],[-1.456017,37.489182],[-1.456053,37.489167]]],[[[-1.455617,37.489192],[-1.455627,37.489174],[-1.455627,37.489174],[-1.455618,37.489191],[-1.455633,37.48921],[-1.455646,37.489225],[-1.455624,37.489237],[-1.455619,37.489256],[-1.455618,37.489256],[-1.455624,37.489237],[-1.455646,37.489225],[-1.455633,37.48921],[-1.455617,37.489192]]],[[[-1.455499,37.489298],[-1.455506,37.489318],[-1.455503,37.489344],[-1.455497,37.489383],[-1.455491,37.489427],[-1.455465,37.489465],[-1.455409,37.489501],[-1.455383,37.489518],[-1.455383,37.489518],[-1.455409,37.489501],[-1.455464,37.489466],[-1.455491,37.489427],[-1.455497,37.489383],[-1.455502,37.489345],[-1.455506,37.489318],[-1.455498,37.489299],[-1.455499,37.489298]]],[[[-1.455301,37