    SELECT 'dunas-embrionarias', '2110', 'Dunas móviles embrionarias', 'Litoral', 'El primer relieve de arena de la playa, de apenas unos decímetros, que se forma donde una planta rastrera frena el viento y la arena se deposita a su alrededor. La construyen la grama de mar (Elymus farctus) y la juncia marina, capaces de crecer hacia arriba a medida que quedan enterradas. Es la duna naciente: si se pisa o se allana, todo el cordón dunar que hay detrás se queda sin recambio.', 0, 37.466605, -1.473536, '#e0c56a', '{"type":"MultiPolygon","coordinates":[[[[-1.460575,37.484126],[-1.46055,37.484073],[-1.460549,37.484071],[-1.460501,37.483967],[-1.460581,37.483783],[-1.460735,37.483673],[-1.460906,37.48374],[-1.460718,37.483805],[-1.460667,37.483854],[-1.460772,37.484241],[-1.460801,37.484304],[-1.460575,37.484126]]],[[[-1.462109,37.483487],[-1.462203,37.483424],[-1.462317,37.483346],[-1.462212,37.483079],[-1.462159,37.482945],[-1.461612,37.48267],[-1.46141,37.482612],[-1.46139,37.48258],[-1.461325,37.482588],[-1.461022,37.4825],[-1.460621,37.482426],[-1.460602,37.482422],[-1.460579,37.482409],[-1.460517,37.482347],[-1.460419,37.482249],[-1.460346,37.482041],[-1.46038,37.481968],[-1.460553,37.481907],[-1.460488,37.482047],[-1.460541,37.482196],[-1.460667,37.482324],[-1.461061,37.482397],[-1.461672,37.482574],[-1.462273,37.482875],[-1.462473,37.483382],[-1.462304,37.483497],[-1.462279,37.483587],[-1.462217,37.483642],[-1.462135,37.483643],[-1.462121,37.483646],[-1.462088,37.483652],[-1.462032,37.483656],[-1.462109,37.483487]]],[[[-1.460544,37.481652],[-1.46058,37.481611],[-1.460619,37.481641],[-1.460639,37.481686],[-1.460631,37.481736],[-1.460601,37.481802],[-1.460544,37.481652]]],[[[-1.465299,37.480844],[-1.465399,37.480775],[-1.465578,37.480651],[-1.465709,37.48045],[-1.465709,37.480373],[-1.465738,37.480283],[-1.465738,37.48018],[-1.465767,37.480077],[-1.465805,37.479973],[-1.465807,37.479955],[-1.465847,37.479578],[-1.465847,37.479577],[-1.465877,37.479508],[-1.466128,37