    UNION ALL
    SELECT 'galeria-ribera', '92D0', 'Galerías y matorrales ribereños termomediterráneos', 'Terrestre', 'La vegetación leñosa de ramblas, arroyos y ríos de caudal irregular, que unos meses llevan agua y otros son un lecho de piedras: adelfares y tarayales. La adelfa (Nerium oleander), de hojas coriáceas y flores rosas, y los tarays (Tamarix), de ramillas finas y flores en espiga, resisten tanto las avenidas violentas como meses de sequía. Toda la adelfa es muy tóxica, incluidas hojas y ramas secas.', 0, 37.439468, -1.487286, '#3f7a5a', '{"type":"MultiPolygon","coordinates":[[[[-1.462217,37.483642],[-1.462279,37.483587],[-1.462304,37.483497],[-1.462473,37.483382],[-1.462273,37.482875],[-1.461672,37.482574],[-1.461061,37.482397],[-1.460667,37.482324],[-1.460541,37.482196],[-1.460488,37.482047],[-1.460553,37.481907],[-1.46063,37.48188],[-1.460601,37.481802],[-1.460631,37.481736],[-1.460639,37.481686],[-1.460619,37.481641],[-1.46058,37.481611],[-1.460544,37.481652],[-1.46048,37.48148],[-1.46237,37.48098],[-1.46408,37.48131],[-1.46416,37.48114],[-1.46475,37.48147],[-1.46508,37.48135],[-1.465237,37.480988],[-1.465293,37.480975],[-1.465328,37.480968],[-1.465686,37.48072],[-1.465707,37.480686],[-1.465877,37.480427],[-1.465897,37.480396],[-1.465963,37.479773],[-1.466113,37.479766],[-1.466228,37.479767],[-1.466357,37.4798],[-1.466473,37.479903],[-1.46653,37.479996],[-1.466602,37.480076],[-1.466659,37.480156],[-1.466731,37.480235],[-1.466832,37.480338],[-1.466918,37.480407],[-1.467004,37.4805],[-1.467105,37.480567],[-1.46722,37.480659],[-1.467321,37.480739],[-1.467421,37.48083],[-1.467508,37.480899],[-1.467591,37.480933],[-1.46716,37.48198],[-1.46565,37.4832],[-1.46445,37.4832],[-1.46413,37.48435],[-1.463707,37.484768],[-1.463674,37.484673],[-1.463631,37.484571],[-1.463531,37.484468],[-1.463459,37.484386],[-1.463372,37.484295],[-1.463272,37.484192],[-1.463186,37.484124],[-1.463071,37.484043],[-1.462926,37.48394],[-1.462811,37.483871],[-1.462696,37.483793],[-1.46261,37.48371],[