    SELECT 'matorral-semiarido', '5330', 'Matorral termomediterráneo semiárido', 'Terrestre', 'El matorral de las zonas más cálidas y secas, allí donde prácticamente no hiela: palmito, espino negro, lentisco, cornicales, bojas, albaidas y esparto sobre laderas pedregosas y llanos soleados. Es un matorral abierto, con suelo desnudo a la vista entre mata y mata, y con muchas especies compartidas con el norte de África. Aguanta sequías de meses y rebrota en cuanto llueve.', 0, 37.501195, -1.449516, '#2f6f4e', '{"type":"MultiPolygon","coordinates":[[[[-1.414263,37.508495],[-1.414304,37.50847],[-1.41442,37.50839],[-1.414535,37.508322],[-1.414679,37.508254],[-1.414823,37.508186],[-1.414981,37.508152],[-1.415183,37.508117],[-1.41537,37.508049],[-1.4155,37.507992],[-1.41563,37.507947],[-1.415774,37.507877],[-1.415947,37.507832],[-1.416076,37.507786],[-1.41622,37.507741],[-1.416378,37.507718],[-1.416494,37.50772],[-1.416609,37.507696],[-1.416753,37.507696],[-1.416954,37.507696],[-1.417141,37.507697],[-1.417256,37.507698],[-1.417386,37.507698],[-1.417558,37.507698],[-1.417731,37.507698],[-1.417889,37.507698],[-1.418062,37.507698],[-1.418177,37.507699],[-1.418306,37.507757],[-1.418464,37.50778],[-1.418637,37.507827],[-1.418838,37.507873],[-1.419039,37.507907],[-1.419226,37.507966],[-1.419442,37.508011],[-1.419643,37.508068],[-1.419815,37.508149],[-1.42003,37.508231],[-1.420203,37.508321],[-1.420375,37.50838],[-1.420504,37.508427],[-1.420619,37.508471],[-1.420749,37.50854],[-1.420892,37.508599],[-1.421022,37.508634],[-1.421165,37.50869],[-1.42128,37.508737],[-1.421424,37.508772],[-1.421539,37.50883],[-1.421639,37.508874],[-1.421754,37.508921],[-1.421912,37.508968],[-1.422027,37.509015],[-1.422142,37.509037],[-1.422168,37.509045],[-1.42117,37.50922],[-1.41995,37.50897],[-1.41591,37.50912],[-1.414263,37.508495]]],[[[-1.42401,37.509451],[-1.424097,37.509466],[-1.424298,37.509512],[-1.424485,37.509557],[-1.424672,37.509616],[-1.424873,37.509672],[-1.425046,37.50972],[-1.425246,37.5