    SELECT 'sabinar-juniperus', '5210', 'Matorrales arborescentes de Juniperus spp.', 'Terrestre', 'Matorral alto o bosquete abierto dominado por enebros y sabinas (Juniperus), arbustos de follaje escamoso o punzante y porte denso que aguantan sequía, viento y suelos casi inexistentes. Sus frutos carnosos y azulados —los gálbulos— alimentan en invierno a zorzales y otras aves, que se encargan de dispersar la semilla. Crecen tan despacio que un ejemplar de dos metros puede tener siglos.', 0, 37.427725, -1.486042, '#3f6b4a', '{"type":"MultiPolygon","coordinates":[[[[-1.486811,37.429698],[-1.486812,37.42964],[-1.486813,37.42964],[-1.486847,37.429641],[-1.487231,37.429487],[-1.487339,37.429392],[-1.487513,37.429384],[-1.487667,37.429343],[-1.487923,37.429235],[-1.488131,37.429142],[-1.488271,37.429133],[-1.488367,37.429023],[-1.48846,37.42904],[-1.488472,37.429088],[-1.488464,37.429152],[-1.488589,37.429085],[-1.488709,37.42905],[-1.488803,37.429009],[-1.488838,37.428945],[-1.488978,37.428937],[-1.489092,37.428901],[-1.489252,37.42886],[-1.489366,37.428835],[-1.48946,37.428799],[-1.489468,37.428731],[-1.489548,37.428689],[-1.489614,37.428722],[-1.489632,37.428812],[-1.489746,37.428782],[-1.489826,37.428756],[-1.489933,37.428721],[-1.490028,37.428669],[-1.490168,37.42866],[-1.4903,37.428683],[-1.490421,37.428642],[-1.490462,37.428568],[-1.490562,37.428548],[-1.490669,37.428518],[-1.49079,37.428466],[-1.490953,37.428405],[-1.49102,37.428358],[-1.491134,37.428328],[-1.491247,37.428318],[-1.491359,37.428352],[-1.491433,37.428321],[-1.491492,37.428343],[-1.491604,37.428381],[-1.491697,37.428382],[-1.491777,37.428357],[-1.49191,37.428327],[-1.491996,37.428339],[-1.492104,37.428271],[-1.492197,37.428262],[-1.492377,37.428211],[-1.492445,37.428159],[-1.492446,37.428117],[-1.49256,37.428023],[-1.492615,37.427934],[-1.492643,37.427881],[-1.49267,37.427844],[-1.492736,37.427856],[-1.492907,37.427948],[-1.493047,37.427918],[-1.493235,37.42782],[-1.493323,37.42772],[-1.493476,37.427