    SELECT 'azufaifar', '5220', 'Matorrales arborescentes de Ziziphus', 'Terrestre', 'Espinares de azufaifo (Ziziphus lotus), matas hemisféricas de ramas entrelazadas y espinas ganchudas que forman islas de sombra sobre llanos áridos. Cada mata levanta un pequeño montículo de arena y hojarasca y guarda debajo humedad, semillas y fauna que fuera no sobreviviría. Es el único hábitat de clima casi desértico de Europa occidental, y por eso figura como prioritario.', 1, 37.501195, -1.449516, '#6f8f3a', '{"type":"MultiPolygon","coordinates":[[[[-1.402925,37.5078],[-1.402842,37.507781],[-1.402669,37.507781],[-1.40254,37.507782],[-1.402425,37.50778],[-1.402295,37.507688],[-1.402195,37.507642],[-1.402081,37.507539],[-1.40208,37.507447],[-1.402081,37.507384],[-1.402081,37.507332],[-1.40211,37.507231],[-1.402168,37.50715],[-1.402194,37.50712],[-1.403042,37.506865],[-1.403148,37.506866],[-1.403263,37.506865],[-1.40345,37.506866],[-1.403543,37.506851],[-1.40381,37.50701],[-1.40415,37.50687],[-1.40455,37.50728],[-1.405517,37.506933],[-1.405633,37.506954],[-1.40572,37.506953],[-1.40572,37.50702],[-1.4064,37.50703],[-1.40638,37.50719],[-1.40747,37.50705],[-1.40799,37.50733],[-1.40814,37.50716],[-1.40888,37.50737],[-1.40928,37.50717],[-1.40955,37.50743],[-1.40978,37.5072],[-1.40991,37.50739],[-1.410613,37.507061],[-1.410793,37.507029],[-1.410821,37.507024],[-1.411096,37.506932],[-1.41257,37.50678],[-1.413394,37.506447],[-1.413523,37.506442],[-1.41529,37.50707],[-1.41682,37.50645],[-1.416894,37.506128],[-1.416979,37.506043],[-1.417073,37.505947],[-1.417312,37.505745],[-1.417549,37.505546],[-1.417911,37.505305],[-1.418262,37.505202],[-1.41831,37.50533],[-1.41875,37.5054],[-1.419503,37.505115],[-1.419819,37.50515],[-1.420355,37.505167],[-1.420961,37.504931],[-1.421206,37.504772],[-1.421447,37.504465],[-1.421751,37.50386],[-1.422034,37.503229],[-1.422302,37.502793],[-1.422317,37.502768],[-1.422417,37.502704],[-1.422662,37.502648],[-1.42275,37.50305],[-1.42308,37.50313],[-1.423319,37.502