    SELECT 'matorral-halonitrofilo', '1430', 'Matorrales halo-nitrófilos', 'Terrestre', 'Matorral de suelos salinos removidos y cargados de nitrógeno: bordes de camino y de cultivo, márgenes de rambla, corrales y escombreras viejas. Lo forman matas robustas de hoja gris o carnosa —orgazas, sosas, bojas y cambroneras— que rebrotan enseguida tras cualquier alteración. Aunque nace de terrenos trastocados, es vegetación propia de los ambientes áridos del sureste y a menudo el último refugio de plantas escasas.', 0, 37.464167, -1.480269, '#9a7b3f', '{"type":"MultiPolygon","coordinates":[[[[-1.420211,37.504846],[-1.420271,37.504848],[-1.420747,37.504665],[-1.420905,37.504561],[-1.421092,37.50432],[-1.42138,37.503747],[-1.421668,37.503107],[-1.421843,37.502823],[-1.421897,37.502734],[-1.42266,37.50264],[-1.422662,37.502648],[-1.422417,37.502704],[-1.422317,37.502768],[-1.422302,37.502793],[-1.422034,37.503229],[-1.421751,37.50386],[-1.421447,37.504465],[-1.421206,37.504772],[-1.420961,37.504931],[-1.420355,37.505167],[-1.419819,37.50515],[-1.419503,37.505115],[-1.420211,37.504846]]],[[[-1.423728,37.502683],[-1.423732,37.502682],[-1.423825,37.502649],[-1.423881,37.502973],[-1.423809,37.502998],[-1.423372,37.502999],[-1.423345,37.502983],[-1.423319,37.502965],[-1.423728,37.502683]]],[[[-1.425069,37.503599],[-1.425179,37.503613],[-1.425304,37.503599],[-1.425672,37.503556],[-1.427964,37.503704],[-1.427416,37.503688],[-1.426815,37.503754],[-1.425824,37.503856],[-1.425177,37.503931],[-1.424753,37.503878],[-1.424659,37.503759],[-1.424646,37.503743],[-1.425069,37.503599]]],[[[-1.42888,37.503235],[-1.428964,37.503213],[-1.429339,37.502927],[-1.429425,37.502663],[-1.429382,37.502353],[-1.429411,37.501975],[-1.429554,37.501686],[-1.429595,37.501604],[-1.429726,37.501457],[-1.429764,37.501414],[-1.4299,37.50138],[-1.430049,37.501167],[-1.430146,37.501102],[-1.430314,37.500988],[-1.43068,37.50101],[-1.430756,37.50079],[-1.430966,37.500716],[-1.431177,37.500678],[-1.431595,37.500606],[-