    SELECT 'rios-glaucium', '3250', 'Ríos mediterráneos de caudal permanente con Glaucium flavum', 'Terrestre', 'Tramos de río con agua todo el año y lecho de gravas y cantos que las crecidas remueven y vuelven a depositar. Sobre esas barras de piedra suelta crece la amapola marina (Glaucium flavum), de hojas de un verde azulado y flores amarillas grandes, junto a otras plantas que aguantan que el sustrato cambie de sitio cada invierno. Es vegetación de terreno inestable: sin crecidas, la maleza la desplaza.', 0, 37.500643, -1.478322, '#6f9270', '{"type":"MultiPolygon","coordinates":[[[[-1.476791,37.502107],[-1.476927,37.502046],[-1.477084,37.502028],[-1.477242,37.502004],[-1.477339,37.501964],[-1.477401,37.50193],[-1.47753,37.501831],[-1.477632,37.501742],[-1.477711,37.50168],[-1.477691,37.501593],[-1.477767,37.501517],[-1.477856,37.501414],[-1.47794,37.501395],[-1.477911,37.501304],[-1.477883,37.501274],[-1.47786,37.501251],[-1.477806,37.501231],[-1.477782,37.501222],[-1.477603,37.501213],[-1.477494,37.501232],[-1.477402,37.501262],[-1.477209,37.501295],[-1.477083,37.501276],[-1.477026,37.501303],[-1.476951,37.501302],[-1.476855,37.501304],[-1.476777,37.501296],[-1.476647,37.501246],[-1.476592,37.501155],[-1.476521,37.501096],[-1.47652,37.501096],[-1.476408,37.501007],[-1.476334,37.500968],[-1.476207,37.50097],[-1.47608,37.501003],[-1.475907,37.501077],[-1.475744,37.501138],[-1.475462,37.501246],[-1.475277,37.501296],[-1.475123,37.501343],[-1.475035,37.501363],[-1.474842,37.501391],[-1.474609,37.501409],[-1.474519,37.501426],[-1.474492,37.50144],[-1.474345,37.501302],[-1.474384,37.501282],[-1.474411,37.501279],[-1.474493,37.501273],[-1.47459,37.501238],[-1.474706,37.501214],[-1.47484,37.501221],[-1.474917,37.501232],[-1.475,37.501233],[-1.475123,37.501214],[-1.47522,37.501154],[-1.475279,37.501119],[-1.475356,37.50108],[-1.475421,37.501045],[-1.475531,37.501026],[-1.475602,37.501006],[-1.475667,37.500951],[-1.475777,37.500896],[-1.475848,37.500887],[-1.475906,37.5