    SELECT 'subestepa-thero-brachypodietea', '6220', 'Zonas subestépicas de gramíneas y anuales del Thero-Brachypodietea', 'Terrestre', 'Pastizales secos en los que conviven gramíneas vivaces de mata dura, como el lastón (Brachypodium retusum) o el esparto, con una multitud de plantas anuales diminutas que nacen con las lluvias y se secan antes del verano. En agosto parecen un erial pardo; en abril pueden reunir cuarenta especies distintas en un metro cuadrado. Esa riqueza escondida es la razón de que sea un hábitat prioritario.', 1, 37.429269, -1.489635, '#b0a066', '{"type":"MultiPolygon","coordinates":[[[[-1.477692,37.432877],[-1.477658,37.432838],[-1.477659,37.432735],[-1.477673,37.43262],[-1.477731,37.43254],[-1.477788,37.432459],[-1.477875,37.432379],[-1.478004,37.4323],[-1.478091,37.432231],[-1.47822,37.432115],[-1.478321,37.432036],[-1.478451,37.431931],[-1.478566,37.431841],[-1.478652,37.431749],[-1.478753,37.431681],[-1.478825,37.431601],[-1.478926,37.431496],[-1.479041,37.431405],[-1.479142,37.431314],[-1.479228,37.431243],[-1.4793,37.431151],[-1.479401,37.431072],[-1.479487,37.43098],[-1.479588,37.430901],[-1.479674,37.430821],[-1.479775,37.43075],[-1.479862,37.430659],[-1.479977,37.430579],[-1.480092,37.430499],[-1.480193,37.430428],[-1.480308,37.430349],[-1.480409,37.430291],[-1.48051,37.430234],[-1.480625,37.430166],[-1.480754,37.430109],[-1.480869,37.430038],[-1.481013,37.429993],[-1.481186,37.429925],[-1.481344,37.429878],[-1.481488,37.429855],[-1.481661,37.429855],[-1.481876,37.429855],[-1.482049,37.429821],[-1.482207,37.429821],[-1.482337,37.429798],[-1.482466,37.429797],[-1.482668,37.42982],[-1.482783,37.42982],[-1.482941,37.429819],[-1.483113,37.429853],[-1.483272,37.429853],[-1.483459,37.429876],[-1.483588,37.429877],[-1.483732,37.429854],[-1.483847,37.429831],[-1.484006,37.429795],[-1.48415,37.429749],[-1.484279,37.429692],[-1.484423,37.429658],[-1.484624,37.4296],[-1.484826,37.42953],[-1.484998,37.429485],[-1.485143,37.42944],[-1.485315,37.429