    SELECT 'Cormorán moñudo', 'Gulosus aristotelis', 'fauna', 'Ave marina', 'Costas rocosas, acantilados e islotes; pesca buceando cerca de la orilla', 'Cormorán marino de plumaje negro con reflejos verdosos, más esbelto que el grande y con la frente empinada. Bucea desde la superficie con un salto característico y persigue peces bajo el agua. Se seca con las alas abiertas sobre las rocas.', NULL, 'Salta hacia arriba antes de sumergirse; Frente muy empinada y pico fino; Se posa en roca con las alas abiertas al sol', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Shag_Phalacrocorax_aristotelis.jpg?width=1280', 'Andreas Trepte (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 4, '{"categoria":"Subespecie mediterránea (desmarestii) catalogada Vulnerable en el Catálogo Español de Especies Amenazadas","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"Subespecie mediterránea (desmarestii) catalogada Vulnerable en el Catálogo Español de Especies Amenazadas","ambito":"estatal","origen":"spainStatus del park.json"}', 1, 1, NULL, 'GBIF confirma su presencia con 165 ocurrencias dentro del espacio (barrido de 2026-08-28); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2, que la cita como «Phalacrocorax aristotelis aristotelis»: población permanente, presente; Decreto n.º 299/2010, Plan de gestión y conservación de la ZEPA Almenara, Moreras y Cabo Cope, §7.3 (fauna catalogada) y §8.3.3 (flora del Catálogo Regional): la norma la enumera en la ZEPA «Sierra de la Almenara, Moreras y Cabo Cope» y su zona de estudio, que el propio plan cifra en unos 510 km² repartidos en cuatro unidades —Almenara 415 km², Carrasquilla 94, Sierra de las Moreras 16 y Cabo Cope 1—. Las tablas dicen «presentes en la ZEPA» y «en la zona de estudio», nunca «en este espacio», que la cita como «Phalacrocorax aristotelis»; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Aves', 'Suliformes', 'Phalacrocoracidae', 'Gulosus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2018)', NULL, 'Subespecie mediterránea (desmarestii) catalogada Vulnerable en el Catálogo Español de Especies Amenazadas', 'Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia (Ley 7/1995): Vulnerable', 'Región de Murcia', 'Reclasificado taxonómicamente de Phalacrocorax aristotelis a Gulosus aristotelis; confirmar si la población litoral pertenece a la subespecie desmarestii.', 80933, 2481861, 165, 'ES0000261', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000261","name":"Almenara-Moreras-Cabo Cope","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2"}'
    UNION ALL
    SELECT 'Tarabilla europea', 'Saxicola rubicola', 'fauna', 'Ave', 'Matorral bajo, herbazales, ribazos y bordes de cultivo con posaderos', 'Pájaro pequeño y regordete que se posa en lo alto de las matas, muy erguido y a la vista, para lanzarse al suelo a por insectos. El macho tiene la cabeza negra, un collar blanco a los lados y el pecho naranja. Su reclamo suena como dos piedras golpeadas, de donde le viene el nombre.', NULL, 'Siempre en lo alto de una mata, bien visible; Macho con capucha negra y medio collar blanco; Reclamo como el chasquido de dos cantos rodados', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Malestonechatseaham_Cropped.jpg?width=1280', 'derivative work: Myosotis Scorpioides (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Listado de Especies Silvestres en Régimen de Protección Especial (LESRPE)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"Listado de Especies Silvestres en Régimen de Protección Especial (LESRPE)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 135 ocurrencias dentro del espacio (barrido de 2026-08-28); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2, que la cita como «Saxicola torquatus»: población permanente, presente; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Muscicapidae', 'Saxicola', 'LC (Preocupación menor)', NULL, 'Listado de Especies Silvestres en Régimen de Protección Especial (LESRPE)', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 16387, 4408759, 135, 'ES0000261', 0, '{"tipos":["permanente"],"etiqueta":"Resi