    SELECT 'Torcecuello euroasiático', 'Jynx torquilla', 'fauna', 'Ave', 'Bosques abiertos, sotos, huertos y arboledas con madera muerta', 'Pariente de los pájaros carpinteros que ni pica la madera ni trepa por los troncos: se posa de través en las ramas y come hormigas del suelo con una lengua larguísima. Su plumaje jaspeado en grises y pardos imita la corteza. Si se le molesta en el nido, retuerce el cuello como una culebra, de ahí su nombre.', NULL, 'Plumaje veteado como corteza, difícil de ver quieto; Se posa a lo largo de la rama, no agarrado al tronco; Franja oscura desde la nuca hasta la mitad de la espalda', 'Paso migratorio e invernada', 'https://commons.wikimedia.org/wiki/Special:FilePath/Jinxtorquilla.jpg?width=1280', 'User:Aelwyn (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 9 ocurrencias dentro del espacio (barrido de 2026-08-28); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2: población en concentración, presente; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Piciformes', 'Picidae', 'Jynx', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2017)', 'DD — Datos insuficientes (Lista Roja española, 2004)', 'Directiva Aves 2009/147/CE (Red Natura 2000); LESRPE', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 12326, 8012314, 9, 'ES0000261', 1, '{"tipos":["en concentración"],"etiqueta":"En paso migratorio","sitios":[{"code":"ES0000261","name":"Almenara-Moreras-Cabo Cope","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2"}'
    UNION ALL
    SELECT 'Águila calzada', 'Hieraaetus pennatus', 'fauna', 'Ave rapaz', 'Bosques y sierras con arbolado, cazando sobre zonas abiertas cercanas', 'Águila pequeña, del tamaño de un ratonero, con dos formas de plumaje muy distintas: una clara con el vientre blanco y otra oscura y uniforme. Nidifica en árboles dentro del bosque y caza en campo abierto lanzándose desde altura. Se identifica en vuelo por las «luces de posición»: dos manchas blancas en el arranque de las alas.', NULL, 'Dos manchas blancas donde el ala se une al cuerpo; Existen ejemplares claros y oscuros de la misma especie; Cola larga y recta, sin la muesca del milano', 'Primavera y verano (estival); algunos ejemplares invernan', 'https://commons.wikimedia.org/wiki/Special:FilePath/Booted_eagle%2C_Hieraaetus_pennatus%2C_at_Kgalagadi_Transfrontier_Pa_(32334023348).jpg?width=1280', 'Derek Keats from Johannesburg, South Africa (CC BY 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 6 ocurrencias dentro del espacio (barrido de 2026-08-28); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2: población permanente; Decreto n.º 299/2010, Plan de gestión y conservación de la ZEPA Almenara, Moreras y Cabo Cope, §7.3 (fauna catalogada) y §8.3.3 (flora del Catálogo Regional): la norma la enumera en la ZEPA «Sierra de la Almenara, Moreras y Cabo Cope» y su zona de estudio, que el propio plan cifra en unos 510 km² repartidos en cuatro unidades —Almenara 415 km², Carrasquilla 94, Sierra de las Moreras 16 y Cabo Cope 1—. Las tablas dicen «presentes en la ZEPA» y «en la zona de estudio», nunca «en este espacio»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Accipitriformes', 'Accipitridae', 'Hieraaetus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2021)', 'NE — No evaluada (Lista Roja española, 2004)', 'Directiva Aves 2009/147/CE (Red Natura 2000); LESRPE', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 11959, 2480685, 6, 'ES0000261', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000261","name":"Almenara-Moreras-Cabo Cope","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2"}'
    UNION ALL
    SELECT 'Búho real', 'Bubo bubo', 'fauna', 'Ave rapaz nocturna', 'Cortados rocosos, barrancos y laderas con matorral y zonas abiertas de caza', 'El mayor búho de Europa, con casi dos metros de envergadura, penachos de plumas erguidos sobre la cabeza y ojos de un naranja encendido. Caza conejos, ratas e incluso otras rapaces. Su canto es un «bu-bo» profundo que se propaga kilómetros por los barrancos en las noches de invierno.', NULL, 'Penachos de plumas erguidos a los lados de la cabeza; Ojos naranjas muy intensos; Canto grave y profundo en las noches de invierno', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bubo_bubo_sibiricus_-_01.JPG?width=1280', 'Carlos Delgado (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)","ambito":"autonómico","origen":"regionalStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 4 ocurrencias dentro del espacio (barrido de 2026-08-28); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2: población permanente; Decreto n.º 299/2010, Plan de gestión y conservación de la ZEPA Almenara, Moreras y Cabo Cope, §7.3 (fauna catalogada) y §8.3.3 (flora del Catálogo Regional): la norma la enumera en la ZEPA «Sierra de la Almenara, Moreras y Cabo Cope» y su zona de estudio, que el propio plan cifra en unos 510 km² repartidos en cuatro unidades —Almenara 415 km², Carrasquilla 94, Sierra de las Moreras 16 y Cabo Cope 1—. Las tablas dicen «presentes en la ZEPA» y «en la zona de estudio», nunca «en este espacio»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Strigiformes', 'Strigidae', 'Bubo', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2017)', 'NE — No evaluada (Lista Roja española, 2004)', 'LESRPE; Directiva Aves 2009/147/CE, Anexo I; Reglamento CITES (CE) 338/97, Anexo A', 'Especies de interés especial (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)', 'Región de Murcia', NULL, 10917, 5959092, 4, 'ES0000261', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000261","name":"Almenara-Moreras-Cabo Cope","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2"}'
