    SELECT 'Águila perdicera', 'Aquila fasciata', 'fauna', 'Ave rapaz', 'Sierras con cortados rocosos y amplias zonas abiertas de matorral y cultivo para cazar', 'Águila mediana de alas largas y cola larga, con el vientre blanco finamente rayado y una mancha blanca en la espalda que se ve bien en vuelo. Caza a gran velocidad y a poca altura, sorprendiendo a perdices, conejos y palomas. Las parejas ocupan el mismo cortado durante años.', NULL, 'Mancha blanca en el centro de la espalda, visible desde arriba; Vientre claro y muy rayado, con una banda oscura en el borde del ala; Vuelo bajo y rápido cuando caza, no en círculos altos', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Aguila_perdicera.jpg?width=1280', 'Paco Gómez from Castellón, Spain (CC BY-SA 2.0) · Wikimedia Commons', NULL, NULL, 4, '{"categoria":"Catálogo Español de Especies Amenazadas: Vulnerable","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 5, '{"categoria":"En Peligro de Extinción (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)","ambito":"autonómico","origen":"regionalStatus del park.json"}', 1, 1, NULL, 'GBIF confirma su presencia con 3 ocurrencias dentro del espacio (barrido de 2026-08-28); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2: población permanente; Decreto n.º 299/2010, Plan de gestión y conservación de la ZEPA Almenara, Moreras y Cabo Cope, §7.3 (fauna catalogada) y §8.3.3 (flora del Catálogo Regional): la norma la enumera en la ZEPA «Sierra de la Almenara, Moreras y Cabo Cope» y su zona de estudio, que el propio plan cifra en unos 510 km² repartidos en cuatro unidades —Almenara 415 km², Carrasquilla 94, Sierra de las Moreras 16 y Cabo Cope 1—. Las tablas dicen «presentes en la ZEPA» y «en la zona de estudio», nunca «en este espacio», que la cita como «Hieraaetus fasciatus»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Accipitriformes', 'Accipitridae', 'Aquila', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)', 'EN — En peligro (Lista Roja española, 2004)', 'Catálogo Español de Especies Amenazadas: Vulnerable; Libro Rojo de las Aves de España (SEO/BirdLife, 2004/2021); Directiva Aves 2009/147/CE, Anexo I', 'En Peligro de Extinción (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)', 'Región de Murcia', NULL, 16302, 5844449, 3, 'ES0000261', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000261","name":"Almenara-Moreras-Cabo Cope","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2"}'
    UNION ALL
    SELECT 'Azor común', 'Accipiter gentilis', 'fauna', 'Ave rapaz', 'Bosques maduros y masas forestales densas con claros', 'Rapaz forestal de alas cortas y anchas y cola larga, diseñada para perseguir presas entre los árboles a gran velocidad. Es esquiva y se ve casi siempre de refilón. La hembra llega a ser un tercio mayor que el macho, una diferencia poco habitual entre las aves.', NULL, 'Ceja blanca marcada sobre el ojo, como un antifaz al revés; Vuelo de varios aleteos rápidos seguidos de un planeo corto; Pecho finamente rayado en horizontal en los adultos', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Northern_Goshawk_ad_M2.jpg?width=1280', 'Norbert Kenntner, Berlin (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 0 ocurrencias dentro del espacio (barrido de 2026-08-28); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2: población permanente; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Accipitriformes', 'Accipitridae', 'Accipiter', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2021)', 'NE — No evaluada (Lista Roja española, 2004)', 'Directiva Aves 2009/147/CE (Red Natura 2000)', 'No incluida en Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia ni en Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de la Región de Murcia ni en Catalogación de la malvasía cabeciblanca (Región de Murcia)', 'Región de Murcia', NULL, 11351, 2480589, 0, 'ES0000261', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000261","name":"Almenara-Moreras-Cabo Cope","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000261 (Almenara-Moreras-Cabo Cope), sección 3.2"}'
